  lock(page_lock(va));
  if (pte_present(va)) { unlock(page_lock(va)); return; }
  frame_t f = alloc_frame();
  if (!f) {handle_out_of_memory(); unlock(page_lock(va)); return;}
  zero_fill(f);
  map(va, f, PRESENT);
  invalidate_TLB(va);
